"""Refresh the local preview fallback. GitHub Pages discovers files at publish time."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[1]
paths = sorted('/' + p.relative_to(root).as_posix()
               for version in ('v1', 'v2')
               for p in (root / 'gallery' / version).iterdir()
               if p.is_file() and p.suffix.lower() in {'.png', '.jpg', '.jpeg', '.webp', '.avif', '.gif'})
(root / 'gallery/local-manifest.js').write_text(
    '// Generated by scripts/build_gallery_manifest.py; local preview fallback.\n'
    'window.lumifyGalleryFiles = ' + json.dumps(paths, indent=2) + ';\n')
print(f'Indexed {len(paths)} gallery images for local preview.')
